    const vd = this._irVorgabeDocks();
    const eigen = (mitRoute && st.r !== undefined) || Array.isArray(st.d);
    const r = mitRoute ? (st.r !== undefined ? st.r : vorgabeR) : 2;
    const docks = Array.isArray(st.d) ? st.d : vd;
