    // kommt die Anmeldung erst nach dem Aushaengen zurueck: gleich wieder abmelden
    const add = (typ, f) => this._hass.connection.subscribeEvents(f, typ).then((u) => { if (this._gestUnsub === liste) liste.push(u); else u(); }, () => {});
